  "data models", "tidyverse",            "dplyr to build, filter and join; tidyr to pivot; ggplot2 for every figure",
  "data models", "xts, zoo",             "the date-indexed matrix every optimizer consumes",
  "the subject", "PortfolioAnalytics",   "portfolio specification and optimization",
