# ===== The shape of the data =====

## ---- dimensions ----
p <- xts::periodicity(R)
c(months = nrow(R), assets = ncol(R),
  from = as.character(start(R)), to = as.character(end(R)), scale = p$scale)

## ---- fig-01-growth ----
# Growth of one dollar in three of the sixteen series, on a log scale. Built
# from one long data frame, one row per date and asset, the shape as_pm()
# returns.
growth <- as_pm(R[, few]) |>
  dplyr::group_by(asset) |>
  dplyr::mutate(growth = cumprod(1 + value)) |>
  dplyr::ungroup()

ggplot2::ggplot(growth, ggplot2::aes(date, growth, colour = asset)) +
  ggplot2::geom_line(linewidth = 0.7) +
  ggplot2::scale_y_log10() +
  scale_colour_tidyaa() +
  ggplot2::labs(x = NULL, y = "growth of one dollar, log scale", colour = NULL) +
  theme_tidyaa()

## ---- growth-end ----
final <- growth |> dplyr::filter(date == max(date))
final <- setNames(final$growth, final$asset)

## ---- tbl-01-annualized ----
# Annualized return, volatility and Sharpe ratio for three series, from
# PerformanceAnalytics on the wide matrix. The bill enters as a vector aligned
# with the rows.
PerformanceAnalytics::table.AnnualizedReturns(R[, few], Rf = rf) |>
  kable(digits = 3)
